import React, { useState } from "react";
import { motion } from "framer-motion";
import { HiMenu, HiX } from "react-icons/hi";
import { useNavigate } from "react-router-dom";

const HomePage = () => {
  const [menuOpen, setMenuOpen] = useState(false);
  const navigate = useNavigate();

  const scrollToSection = (id) => {
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: "smooth" });
      setMenuOpen(false);
    }
  };

  const videoSource = "/videos/EcoPackaging.mov";

  return (
    <div className="w-full min-h-screen bg-gradient-to-b from-green-50 to-white font-sans overflow-x-hidden">
      {/* Navbar */}
      <nav className="w-full bg-green-50 shadow-md fixed top-0 left-0 z-50">
        <div className="max-w-7xl mx-auto px-8 md:px-20 flex items-center justify-between h-20">
          <div className="flex items-center space-x-3 cursor-pointer">
            <img
              src="/images/ecoLogo.png"
              alt="EcoPack AI Logo"
              className="w-12 h-12 rounded-full object-cover shadow-md hover:scale-110 transform transition duration-300"
            />
            <span className="text-2xl font-bold text-green-700">
              EcoPack <span className="text-green-600">AI</span>
            </span>
          </div>

          {/* Desktop Menu */}
          <ul className="hidden md:flex space-x-8 text-green-700 font-semibold">
            <li onClick={() => scrollToSection("hero")} className="hover:text-green-900 cursor-pointer transition">Home</li>
            <li onClick={() => scrollToSection("about")} className="hover:text-green-900 cursor-pointer transition">About</li>
            <li className="hover:text-green-900 cursor-pointer transition">Login/Signup</li>
          </ul>

          {/* Mobile Menu Button */}
          <div className="md:hidden">
            <button onClick={() => setMenuOpen(!menuOpen)}>
              {menuOpen ? <HiX size={28} /> : <HiMenu size={28} />}
            </button>
          </div>
        </div>

        {menuOpen && (
          <div className="md:hidden bg-green-50 shadow-md px-4 py-4 flex flex-col space-y-4 text-green-700 font-semibold">
            <li onClick={() => scrollToSection("hero")} className="cursor-pointer hover:text-green-900">Home</li>
            <li onClick={() => scrollToSection("about")} className="cursor-pointer hover:text-green-900">About</li>
            <li className="cursor-pointer hover:text-green-900">Login/Signup</li>
          </div>
        )}
      </nav>

      {/* ---------------- FULL-SCREEN HERO SECTION ---------------- */}
      <section
        id="hero"
        className="relative flex items-center justify-center text-center md:text-left px-6 md:px-20 h-screen overflow-hidden"
      >
        {/* Fullscreen Background Video */}
        <video
          autoPlay
          loop
          muted
          playsInline
          className="absolute inset-0 w-full h-full object-cover z-0 opacity-25"
        >
          <source src={videoSource} type="video/mp4" />
          Your browser does not support the video tag.
        </video>

        {/* Overlay for better text visibility */}
        <div className="absolute inset-0 bg-gradient-to-b from-green-50/60 to-green-100/40 z-0"></div>

        {/* Hero Content */}
        <motion.div
          className="relative z-10 text-center md:text-left max-w-3xl"
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 1 }}
        >
          <h1 className="text-4xl md:text-6xl font-bold text-green-900 leading-tight mb-4">
            Welcome to <span className="text-green-600">EcoPack AI</span>
          </h1>
          <p className="text-gray-800 text-lg md:text-xl mb-8">
            Revolutionizing packaging with AI-driven eco-friendly solutions.
            Reduce waste, save resources, and make a positive impact on our
            planet.
          </p>

          <div className="flex flex-col md:flex-row justify-center md:justify-start gap-4">
            <button
              onClick={() => navigate("/get-started")}
              className="bg-green-600 text-white px-8 py-3 rounded-lg shadow-lg hover:bg-green-700 transform hover:scale-105 transition duration-300"
            >
              Get Started
            </button>
            <button
              onClick={() => navigate("/learn-more")}
              className="bg-white text-green-600 border-2 border-green-600 px-8 py-3 rounded-lg shadow-lg hover:bg-green-50 transform hover:scale-105 transition duration-300"
            >
              Learn More
            </button>
          </div>
        </motion.div>
      </section>
      {/* ---------------------------------------------------------- */}
      

      {/* FEATURES SECTION */}
      <section className="bg-green-50 py-20 px-8 md:px-20 text-center">
        <h2 className="text-3xl md:text-4xl font-bold text-green-800 mb-12">
          Features
        </h2>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {[
            {
              title: "AI-Powered Analysis",
              description:
                "Smart recommendations for sustainable packaging based on AI insights.",
            },
            {
              title: "Eco-Friendly Materials",
              description:
                "Discover biodegradable, recyclable, and reusable packaging options.",
            },
            {
              title: "Track & Reduce Waste",
              description:
                "Monitor packaging impact and optimize for minimal environmental footprint.",
            },
          ].map((feature, idx) => (
            <motion.div
              key={idx}
              className="bg-white p-8 rounded-3xl shadow-xl hover:shadow-2xl transform hover:scale-105 transition duration-500"
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.8, delay: idx * 0.2 }}
            >
              <h2 className="text-2xl font-semibold text-green-700 mb-4">
                {feature.title}
              </h2>
              <p className="text-gray-600">{feature.description}</p>
            </motion.div>
          ))}
        </div>
      </section>

      {/* (Keep the rest of your sections unchanged — About, CTA, Footer, etc.) */}
    </div>
  );
};

export default HomePage;
